import { Container } from "@needle-di/core";
import { HTTPService } from "./core/services/http-service.ts";
import { DatabaseService } from "./core/services/database-service.ts";
import { logDiscordBotConfiguration } from "./api/versions/v1/utils/discord-bot-config-utils.ts";
import { cleanupExpiredAuthenticationChallenges } from "../crons/cleanup-authentication-challenges-cron.ts";
import { cleanupExpiredRefreshTokens } from "../crons/cleanup-refresh-tokens-cron.ts";
import { cleanupStaleUserSessions } from "../crons/cleanup-user-sessions-cron.ts";

// Re-export the Durable Object so it is included in the Worker bundle and the
// `GAME_HUB` binding resolves to it.
export { GameHub } from "./core/durable-objects/game-hub.ts";

const container = new Container();

let httpService: HTTPService | null = null;
let databaseService: DatabaseService | null = null;

function getDatabaseService(): DatabaseService {
  if (databaseService === null) {
    databaseService = container.get(DatabaseService);
    databaseService.init();
  }

  return databaseService;
}

function getHTTPService(): HTTPService {
  if (httpService === null) {
    getDatabaseService();
    logDiscordBotConfiguration();
    httpService = container.get(HTTPService);
  }

  return httpService;
}

export default {
  async fetch(request: Request, _env: Env): Promise<Response> {
    return getHTTPService().fetch(request);
  },

  async scheduled(_controller: ScheduledController, _env: Env): Promise<void> {
    const databaseService = getDatabaseService();

    // Hourly maintenance crons (trigger `0 * * * *`).
    await Promise.all([
      cleanupExpiredAuthenticationChallenges(databaseService),
      cleanupExpiredRefreshTokens(databaseService),
      cleanupStaleUserSessions(databaseService),
    ]);
  },
} satisfies ExportedHandler<Env>;
