import { inject, injectable } from "@needle-di/core";
import { ServerError } from "../models/server-error.ts";
import { CryptoUtils } from "../../../../core/utils/crypto-utils.ts";
import { UserEncryptionKeysService } from "./user-encryption-keys-service.ts";

@injectable()
export class CryptoService {
  private static readonly IV_LENGTH = 12;

  constructor(
    private userEncryptionKeysService = inject(UserEncryptionKeysService),
  ) {}

  public async encryptForUser(
    userId: string,
    data: ArrayBuffer,
  ): Promise<ArrayBuffer> {
    const key: string | null = await this.userEncryptionKeysService.get(userId);

    if (key === null) {
      throw new ServerError(
        "NO_USER_KEY",
        "No user key found for this user",
        400,
      );
    }

    const cryptoKey: CryptoKey = await CryptoUtils.base64ToCryptoKey(
      key,
      {
        name: "AES-GCM",
        length: 256,
      },
      ["encrypt"],
    );

    return this.encryptData(cryptoKey, data);
  }

  public async decryptForUser(
    userId: string,
    encryptedData: ArrayBuffer,
  ): Promise<ArrayBuffer> {
    const key: string | null = await this.userEncryptionKeysService.get(userId);

    if (key === null) {
      throw new ServerError(
        "NO_USER_KEY",
        "No user key found for this user",
        400,
      );
    }

    const cryptoKey: CryptoKey = await CryptoUtils.base64ToCryptoKey(
      key,
      {
        name: "AES-GCM",
        length: 256,
      },
      ["decrypt"],
    );

    return this.decryptData(cryptoKey, encryptedData);
  }

  private async encryptData(
    cryptoKey: CryptoKey,
    data: ArrayBuffer,
  ): Promise<ArrayBuffer> {
    const iv = crypto.getRandomValues(new Uint8Array(CryptoService.IV_LENGTH)); // IV remains Uint8Array

    // Encrypt the data using the cryptoKey
    const encryptedData = await crypto.subtle.encrypt(
      {
        name: "AES-GCM",
        iv,
      },
      cryptoKey,
      data,
    );

    // Combine IV and encrypted data into a single ArrayBuffer
    const result = new Uint8Array(iv.length + encryptedData.byteLength);
    result.set(iv, 0); // Copy IV to the beginning
    result.set(new Uint8Array(encryptedData), iv.length); // Append encrypted data

    return result.buffer;
  }

  private async decryptData(
    cryptoKey: CryptoKey,
    encryptedData: ArrayBuffer,
  ): Promise<ArrayBuffer> {
    const encryptedArray = new Uint8Array(encryptedData);

    // Guard against payloads that are too short for AES-GCM IV
    if (encryptedArray.byteLength <= CryptoService.IV_LENGTH) {
      throw new ServerError(
        "INVALID_PAYLOAD",
        "Encrypted payload too short",
        400,
      );
    }

    // Extract IV (first 12 bytes) and encrypted data
    const iv = encryptedArray.subarray(0, CryptoService.IV_LENGTH);
    const data = encryptedArray.subarray(CryptoService.IV_LENGTH);

    // Decrypt the data using the cryptoKey
    try {
      const decryptedData = await crypto.subtle.decrypt(
        {
          name: "AES-GCM",
          iv,
        },
        cryptoKey,
        data,
      );

      return decryptedData;
    } catch {
      throw new ServerError(
        "DECRYPT_FAILED",
        "Invalid or corrupted ciphertext",
        400,
      );
    }
  }
}
